// ============================================================
// 刻晴（Keqing）动态皮肤插件 · 客户端（v2 自适应画框）
// ------------------------------------------------------------
// 任何 DeepSeek Harness 用户均可直接使用，零配置：
//   cordis_define → 新建插件（idPrefix 如 "keqing"），
//                   把本文件全部内容粘贴到 code.client；
//   cordis_run   → 在授权卡片上确认即可。
// 素材（3 张网页壁纸 + 中文大招语音「雷厉风行！」）已内嵌为
// base64 数据 URI，不依赖任何本地文件。
// 可选全画质模式：配合同目录 host.js 使用（自动检测并切换到
// 原图素材，需在 host.js 中把 ASSET_DIR 改成素材文件夹路径）。
// 交互：左键点击 = 释放元素爆发「天街巡游」；拖动 = 移动；
// 右键 = 菜单（释放大招 / 切换壁纸 / 收起 / 一键卸载，
// 卸载需二次确认）；卡片左上角 🖼 按钮 = 快速切换壁纸。
// v2：卡片按每张壁纸的宽高比自适应（最大 320×430px），
// 整张立绘完整展示，不再被方块裁剪。
// ============================================================
const WALLPAPERS = [{"id":"school","name":"校服 · 抱臂","ar":0.5273,"uri":"data:image/jpeg;base64,"},{"id":"sword","name":"持剑 · 战斗","ar":1.6293,"uri":"data:image/jpeg;base64,"},{"id":"shirt","name":"白衬衫 · 桌面","ar":0.5884,"uri":"data:image/jpeg;base64,"}]
const BURST_DATA_URI = 'data:audio/ogg;base64,'

const CSS = `
.keq-root { position: fixed; z-index: 99990; pointer-events: auto; user-select: none; -webkit-user-select: none; touch-action: none; }
.keq-card { position: relative; cursor: pointer; }
.keq-img { display: block; width: 100%; height: 100%; object-fit: cover; border-radius: inherit;
  border: 1px solid rgba(200, 160, 255, .5); background: #150f26;
  box-shadow: 0 14px 48px rgba(0, 0, 0, .5), 0 0 0 1px rgba(190, 150, 255, .14) inset;
  animation: keq-bob 3.6s ease-in-out infinite; }
.keq-card:hover .keq-img { box-shadow: 0 14px 54px rgba(150, 90, 255, .5), 0 0 30px rgba(190, 140, 255, .4); }
@keyframes keq-bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-7px); } }
.keq-is-bursting .keq-img { animation: keq-shake .55s ease-in-out; }
@keyframes keq-shake {
  0% { transform: translate(0, 0) rotate(0deg); }
  15% { transform: translate(-12px, 4px) rotate(-2.5deg); }
  30% { transform: translate(12px, -5px) rotate(2.5deg); }
  45% { transform: translate(-10px, 3px) rotate(-1.8deg); }
  60% { transform: translate(9px, -3px) rotate(1.8deg); }
  80% { transform: translate(-4px, 0) rotate(-.6deg); }
  100% { transform: translate(0, 0) rotate(0deg); }
}
.keq-burst { position: absolute; inset: 0; border-radius: inherit; pointer-events: none; overflow: visible; }
.keq-flash { position: absolute; inset: 0; border-radius: inherit;
  background: radial-gradient(circle at 50% 42%, rgba(244, 226, 255, .96), rgba(178, 118, 255, .55) 45%, rgba(84, 34, 190, .18) 75%, transparent 100%);
  animation: keq-flash .6s ease-out forwards; }
@keyframes keq-flash { 0% { opacity: 0; } 12% { opacity: 1; } 100% { opacity: 0; } }
.keq-shock { position: absolute; left: 50%; top: 50%; width: 230px; height: 230px; margin: -115px 0 0 -115px; border-radius: 50%;
  border: 5px solid rgba(206, 162, 255, .95); animation: keq-shock .7s cubic-bezier(.1, .7, .3, 1) forwards; }
.keq-shock2 { position: absolute; left: 50%; top: 50%; width: 170px; height: 170px; margin: -85px 0 0 -85px; border-radius: 50%;
  border: 3px solid rgba(232, 205, 255, .85); animation: keq-shock .75s cubic-bezier(.1, .7, .3, 1) .12s forwards; }
@keyframes keq-shock { 0% { transform: scale(.2); opacity: .95; } 100% { transform: scale(2.15); opacity: 0; } }
.keq-slash { position: absolute; height: 5px; border-radius: 4px; opacity: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 250, 255, .98) 30%, rgba(190, 140, 255, .95) 60%, transparent);
  filter: drop-shadow(0 0 10px rgba(190, 140, 255, .95)); }
.keq-slash-1 { left: -30%; top: 24%; width: 160%; transform: rotate(-24deg); animation: keq-slash-a .55s ease-out .04s forwards; }
.keq-slash-2 { left: -30%; top: 44%; width: 160%; transform: rotate(-10deg); animation: keq-slash-b .55s ease-out .1s forwards; }
.keq-slash-3 { left: -30%; top: 62%; width: 160%; transform: rotate(6deg); animation: keq-slash-a .55s ease-out .16s forwards; }
.keq-slash-4 { left: -30%; top: 80%; width: 160%; transform: rotate(20deg); animation: keq-slash-b .55s ease-out .22s forwards; }
.keq-slash-5 { left: 10%; top: -20%; width: 5px; height: 140%; transform: rotate(34deg); animation: keq-slash-c .6s ease-out .28s forwards; }
@keyframes keq-slash-a { 0% { opacity: 0; transform: translateX(0) rotate(-24deg) scaleX(.4); } 15% { opacity: 1; } 100% { opacity: 0; transform: translateX(180px) rotate(-24deg) scaleX(1.1); } }
@keyframes keq-slash-b { 0% { opacity: 0; transform: translateX(0) rotate(6deg) scaleX(.4); } 15% { opacity: 1; } 100% { opacity: 0; transform: translateX(-180px) rotate(6deg) scaleX(1.1); } }
@keyframes keq-slash-c { 0% { opacity: 0; transform: translateY(80px) rotate(34deg) scaleY(.3); } 15% { opacity: 1; } 100% { opacity: 0; transform: translateY(-150px) rotate(34deg) scaleY(1.2); } }
.keq-bolt { position: absolute; top: -14%; height: 132%; opacity: 0;
  background: linear-gradient(180deg, #ffffff 0%, #f0dcff 26%, #c99bff 58%, #9a5cff 82%, rgba(122, 63, 255, 0) 100%);
  clip-path: polygon(52% 0%, 100% 0%, 71% 9%, 92% 9%, 58% 27%, 82% 27%, 45% 50%, 68% 50%, 34% 75%, 52% 75%, 18% 100%, 34% 66%, 12% 66%, 38% 42%, 16% 42%, 42% 20%, 20% 20%);
  filter: drop-shadow(0 0 14px rgba(160, 90, 255, .95));
  animation: keq-bolt .85s ease-out forwards; }
.keq-bolt-1 { left: 14%; width: 26px; animation-delay: .06s; }
.keq-bolt-2 { left: 47%; width: 32px; animation-delay: .16s; }
.keq-bolt-3 { left: 76%; width: 22px; animation-delay: .26s; }
@keyframes keq-bolt {
  0% { opacity: 0; transform: translateY(-40px) scaleY(.4); }
  6% { opacity: 1; } 16% { opacity: .35; } 26% { opacity: 1; } 36% { opacity: .55; }
  60% { opacity: .85; } 100% { opacity: 0; transform: translateY(14px) scaleY(1.06); }
}
.keq-shards { position: absolute; inset: 0; }
.keq-shard { position: absolute; left: 50%; top: 50%; width: 10px; height: 10px; margin: -5px 0 0 -5px; border-radius: 2px;
  background: linear-gradient(135deg, #f4e6ff, #c894ff 60%, #7a3fff);
  box-shadow: 0 0 12px rgba(190, 140, 255, .95); opacity: 0;
  animation: keq-shard-fly .8s ease-out forwards; }
@keyframes keq-shard-fly {
  0% { opacity: 0; transform: translate(0, 0) scale(.4); }
  12% { opacity: 1; }
  100% { opacity: 0; transform: translate(var(--dx), var(--dy)) scale(1.15) rotate(220deg); }
}
.keq-skill { position: absolute; left: 0; right: 0; top: -48px; text-align: center; white-space: nowrap;
  color: #e6cfff; font: 700 19px/1 'Microsoft YaHei', sans-serif; text-shadow: 0 0 14px rgba(190, 140, 255, .95), 0 1px 2px #000;
  animation: keq-text .95s ease-out forwards; }
.keq-line { position: absolute; left: 0; right: 0; bottom: -58px; text-align: center; white-space: nowrap;
  color: #f6eeff; font: 700 24px/1 'Microsoft YaHei', sans-serif; letter-spacing: 4px; text-shadow: 0 0 16px rgba(190, 140, 255, .95), 0 1px 3px #000;
  animation: keq-line-in 1.9s ease-out forwards; }
@keyframes keq-text { 0% { opacity: 0; transform: translateY(8px); } 20% { opacity: 1; transform: translateY(0); } 70% { opacity: 1; } 100% { opacity: 0; transform: translateY(-6px); } }
@keyframes keq-line-in { 0% { opacity: 0; transform: scale(.85); } 12% { opacity: 1; transform: scale(1); } 80% { opacity: 1; } 100% { opacity: 0; } }
.keq-close { position: absolute; right: -12px; top: -12px; width: 30px; height: 30px; border: none; border-radius: 50%;
  background: rgba(20, 12, 36, .85); color: #e0c9ff; font: 700 17px/30px sans-serif; cursor: pointer; padding: 0;
  box-shadow: 0 2px 8px rgba(0, 0, 0, .5); }
.keq-close:hover { background: rgba(110, 50, 200, .9); color: #fff; }
.keq-wall { position: absolute; left: -12px; top: -12px; width: 30px; height: 30px; border: none; border-radius: 50%;
  background: rgba(20, 12, 36, .85); color: #e0c9ff; font: 700 14px/30px sans-serif; cursor: pointer; padding: 0;
  box-shadow: 0 2px 8px rgba(0, 0, 0, .5), 0 0 0 1px rgba(200, 160, 255, .3) inset; }
.keq-wall:hover { background: rgba(110, 50, 200, .9); color: #fff; }
.keq-warn { position: absolute; left: 32px; top: -12px; width: 26px; height: 26px; border-radius: 50%; background: #b3402e; color: #fff; text-align: center; font: 700 14px/26px sans-serif; box-shadow: 0 2px 8px rgba(0, 0, 0, .5); }
.keq-pill { position: fixed; z-index: 99990; pointer-events: auto; border: 1px solid rgba(200, 160, 255, .6); border-radius: 999px; padding: 10px 22px;
  background: rgba(18, 12, 36, .92); color: #ecdfff; font: 700 16px/1.4 'Microsoft YaHei', sans-serif; cursor: pointer; user-select: none;
  box-shadow: 0 6px 18px rgba(0, 0, 0, .5); }
.keq-pill:hover { background: rgba(70, 36, 140, .95); }
.keq-menu-backdrop { position: fixed; inset: 0; z-index: 99998; }
.keq-menu { position: fixed; z-index: 99999; min-width: 210px; padding: 6px; border-radius: 12px;
  background: rgba(16, 10, 30, .96); border: 1px solid rgba(200, 160, 255, .4); box-shadow: 0 10px 30px rgba(0, 0, 0, .55);
  color: #ecdfff; font: 13px/1.3 'Microsoft YaHei', sans-serif; }
.keq-menu-item { padding: 9px 14px; border-radius: 8px; cursor: pointer; white-space: nowrap; }
.keq-menu-item:hover { background: rgba(96, 50, 200, .55); }
.keq-menu-item.cur { color: #fff; background: rgba(96, 50, 200, .35); }
.keq-menu-item.danger { color: #ffb4a8; }
.keq-menu-item.danger:hover { background: rgba(200, 60, 60, .6); color: #fff; }
.keq-menu-sep { height: 1px; background: rgba(200, 160, 255, .18); margin: 4px 6px; }
.keq-menu-label { padding: 6px 14px 2px; color: rgba(236, 223, 255, .55); font-size: 11px; letter-spacing: 1px; }
`

return {
  apply(ctx) {
    const slots = ctx.get('slots')
    if (slots === undefined) return
    const disposeStyle = styles.insert(CSS)
    ctx.effect(() => disposeStyle)
    const VOICE_TEXT = '雷厉风行！'
    const SKILL_TEXT = '元素爆发 · 天街巡游'
    const PARTICLE_COUNT = 22
    let disposeSlot = null

    const uninstallAll = async () => {
      try { await host.call('keqing-uninstall', null) } catch (e) { console.warn('keqing-skin: host uninstall call failed', e) }
      try { if (disposeSlot !== null) disposeSlot() } catch (e) { console.warn('keqing-skin: slot dispose failed', e) }
      try { disposeStyle() } catch (e) { console.warn('keqing-skin: style dispose failed', e) }
      console.log('keqing-skin: 皮肤已卸载（UI 与素材路由已移除）。如需彻底删除插件记录，请对 AI 说：cordis_undefine')
    }

    function KeqingWidget() {
      // 素材地址：默认内嵌 data URI（零配置可用）；若加载了 host.js 全画质模式，自动切换为路由地址。
      const [wallpapers, setWallpapers] = React.useState(WALLPAPERS)
      const [burstSrc, setBurstSrc] = React.useState(BURST_DATA_URI)
      const [wallIdx, setWallIdx] = React.useState(0)
      const [imgFailed, setImgFailed] = React.useState(false)
      const [bursting, setBursting] = React.useState(false)
      const [burstKey, setBurstKey] = React.useState(0)
      const [hidden, setHidden] = React.useState(false)
      const [menu, setMenu] = React.useState(null)
      const [confirmUninstall, setConfirmUninstall] = React.useState(false)
      const [pos, setPos] = React.useState(() => ({
        x: Math.max(8, window.innerWidth - 400),
        y: Math.max(8, window.innerHeight - 540),
      }))
      const posRef = React.useRef(pos)
      posRef.current = pos
      const audioRef = React.useRef(null)
      const movedRef = React.useRef(false)

      // 画框自适应：按壁纸宽高比放大到最大 320 宽 / 430 高，始终完整展示整张立绘。
      const fitSize = (ar) => {
        if (!(ar > 0)) return { w: 320, h: 320 }
        let w = 320
        let h = w / ar
        if (h > 430) { h = 430; w = h * ar }
        return { w: Math.round(w), h: Math.round(h) }
      }
      const [dims, setDims] = React.useState(() => {
        const first = WALLPAPERS.length > 0 ? WALLPAPERS[0] : null
        return fitSize(first && first.ar ? first.ar : 0)
      })
      const radius = Math.max(14, Math.min(28, Math.round(Math.min(dims.w, dims.h) * 0.1)))

      React.useEffect(() => {
        const protocol = window.location.protocol
        if (protocol !== 'http:' && protocol !== 'https:') return
        host.call('keqing-urls', null).then((r) => {
          if (!r) return
          if (Array.isArray(r.walls) && r.walls.length === wallpapers.length &&
              r.walls.every((u) => typeof u === 'string')) {
            const origin = window.location.origin
            setWallpapers(wallpapers.map((w, i) => ({ ...w, uri: origin + r.walls[i] })))
          }
          if (typeof r.burst === 'string') setBurstSrc(window.location.origin + r.burst)
        }).catch(() => {})
      }, [])

      React.useEffect(() => () => {
        if (audioRef.current) { try { audioRef.current.pause() } catch (e) {} }
      }, [])

      const switchWallpaper = (idx) => {
        const n = wallpapers.length
        if (n === 0) return
        const next = ((idx % n) + n) % n
        setWallIdx(next)
        setImgFailed(false)
        const w = wallpapers[next]
        if (w && w.ar) setDims(fitSize(w.ar))
      }

      const onImgLoad = (e) => {
        const el = e.target
        if (el && el.naturalWidth > 0 && el.naturalHeight > 0) {
          setDims(fitSize(el.naturalWidth / el.naturalHeight))
        }
      }

      const triggerBurst = () => {
        setBurstKey((k) => k + 1)
        setBursting(true)
        try {
          if (audioRef.current) { try { audioRef.current.pause() } catch (e) {} }
          const audio = new Audio(burstSrc)
          audioRef.current = audio
          const playing = audio.play()
          if (playing !== undefined && playing.catch) playing.catch((err) => console.warn('keqing-skin: voice play failed', err))
        } catch (err) {
          console.error('keqing-skin: audio failed', err)
        }
      }

      const onPointerDown = (e) => {
        if (e.pointerType === 'mouse' && e.button !== 0) return
        movedRef.current = false
        const startX = e.clientX
        const startY = e.clientY
        const startPos = posRef.current
        const move = (ev) => {
          const dx = ev.clientX - startX
          const dy = ev.clientY - startY
          if (Math.abs(dx) + Math.abs(dy) > 6) movedRef.current = true
          setPos({
            x: Math.max(-180, Math.min(window.innerWidth - 90, startPos.x + dx)),
            y: Math.max(-180, Math.min(window.innerHeight - 90, startPos.y + dy)),
          })
        }
        const up = () => {
          window.removeEventListener('pointermove', move)
          window.removeEventListener('pointerup', up)
        }
        window.addEventListener('pointermove', move)
        window.addEventListener('pointerup', up)
      }

      const openMenu = (e, mode) => {
        e.preventDefault()
        e.stopPropagation()
        setConfirmUninstall(false)
        setMenu({
          x: Math.min(e.clientX, window.innerWidth - 240),
          y: Math.min(e.clientY, window.innerHeight - 260),
          mode,
        })
      }

      const menuItem = (label, onClick, extraCls) => React.createElement('div', {
        className: 'keq-menu-item' + (extraCls ? ' ' + extraCls : ''),
        onClick: (e) => { e.stopPropagation(); onClick() },
      }, label)

      const renderMenu = () => {
        if (menu === null) return null
        const items = []
        if (menu.mode === 'card') {
          items.push(menuItem('释放元素爆发「天街巡游」', () => { setMenu(null); triggerBurst() }))
          items.push(React.createElement('div', { key: 'wall-label', className: 'keq-menu-label' }, '切换壁纸'))
          wallpapers.forEach((w, i) => {
            items.push(menuItem(
              (i === wallIdx ? '✓ ' : '　') + w.name,
              () => { setMenu(null); switchWallpaper(i) },
              i === wallIdx ? 'cur' : undefined,
            ))
          })
          items.push(menuItem('收起皮肤', () => { setMenu(null); setHidden(true) }))
        } else {
          items.push(menuItem('显示皮肤', () => { setMenu(null); setHidden(false) }))
        }
        items.push(React.createElement('div', { key: 'sep', className: 'keq-menu-sep' }))
        items.push(menuItem(
          confirmUninstall ? '再次点击：确认卸载' : '一键卸载',
          () => {
            if (confirmUninstall) { setMenu(null); uninstallAll() }
            else setConfirmUninstall(true)
          },
          'danger',
        ))
        return React.createElement('div', {
          className: 'keq-menu-backdrop',
          onClick: () => setMenu(null),
          onContextMenu: (e) => { e.preventDefault(); setMenu(null) },
        },
          React.createElement('div', { className: 'keq-menu', style: { left: menu.x, top: menu.y }, onClick: (e) => e.stopPropagation() }, items))
      }

      const pill = React.createElement('button', {
        className: 'keq-pill',
        style: { left: pos.x, top: pos.y },
        onPointerDown: onPointerDown,
        onClick: () => setHidden(false),
        onContextMenu: (e) => openMenu(e, 'pill'),
        title: '刻晴皮肤（右键菜单）',
      }, '刻晴 ✦')

      const burstLayer = bursting
        ? React.createElement('div', { className: 'keq-burst', key: 'burst-' + burstKey },
            React.createElement('div', { className: 'keq-flash' }),
            React.createElement('div', { className: 'keq-shock' }),
            React.createElement('div', { className: 'keq-shock2' }),
            React.createElement('div', { className: 'keq-slash keq-slash-1' }),
            React.createElement('div', { className: 'keq-slash keq-slash-2' }),
            React.createElement('div', { className: 'keq-slash keq-slash-3' }),
            React.createElement('div', { className: 'keq-slash keq-slash-4' }),
            React.createElement('div', { className: 'keq-slash keq-slash-5' }),
            React.createElement('div', { className: 'keq-bolt keq-bolt-1' }),
            React.createElement('div', { className: 'keq-bolt keq-bolt-2' }),
            React.createElement('div', { className: 'keq-bolt keq-bolt-3' }),
            React.createElement('div', { className: 'keq-shards' },
              Array.from({ length: PARTICLE_COUNT }, (_, i) => React.createElement('span', {
                key: i,
                className: 'keq-shard',
                style: {
                  '--dx': ((i % 5) - 2) * 100 + ((i * 13) % 19) - 9 + 'px',
                  '--dy': ((Math.floor(i / 5) % 3) - 1) * 118 - 70 + 'px',
                  animationDelay: (i % 4) * 0.03 + 's',
                },
              }))),
            React.createElement('div', { className: 'keq-skill' }, SKILL_TEXT),
            React.createElement('div', { className: 'keq-line', onAnimationEnd: () => setBursting(false) }, '“' + VOICE_TEXT + '”'),
          )
        : null

      const card = React.createElement('div', {
        className: 'keq-root',
        style: { left: pos.x, top: pos.y },
        onPointerDown: onPointerDown,
      },
        React.createElement('div', {
          className: 'keq-card' + (bursting ? ' keq-is-bursting' : ''),
          style: { width: dims.w, height: dims.h, borderRadius: radius },
          onClick: () => { if (!movedRef.current) triggerBurst() },
          onContextMenu: (e) => openMenu(e, 'card'),
          title: '点击：释放元素爆发「天街巡游」；右键：菜单',
        },
          React.createElement('img', {
            className: 'keq-img',
            src: wallpapers.length > 0 ? wallpapers[wallIdx].uri : '',
            draggable: false,
            alt: '刻晴',
            onError: () => setImgFailed(true),
            onLoad: onImgLoad,
          }),
          burstLayer,
          React.createElement('button', {
            className: 'keq-wall',
            title: '切换壁纸',
            onClick: (e) => { e.stopPropagation(); switchWallpaper(wallIdx + 1) },
          }, '🖼'),
          imgFailed
            ? React.createElement('div', { className: 'keq-warn', title: '图片素材加载失败' }, '⚠')
            : null,
          React.createElement('button', {
            className: 'keq-close',
            title: '收起皮肤',
            onClick: (e) => { e.stopPropagation(); setHidden(true) },
          }, '×'),
        ))

      return React.createElement(React.Fragment, null, hidden ? pill : card, renderMenu())
    }

    slots.inject('shell.overlay', () => {
      disposeSlot = slots.register(
        { name: 'shell.overlay', id: 'keqing-skin-widget', order: 100, label: '刻晴动态皮肤' },
        () => React.createElement(KeqingWidget),
      )
      return disposeSlot
    })
  },
}
